query($owner:String!, $name:String!, $after:String) {
  rateLimit{cost}
  repository(owner:$owner, name:$name) {
    issues(states:OPEN, first:100, after:$after, orderBy:{field:CREATED_AT, direction:ASC}) {
      totalCount pageInfo{hasNextPage endCursor}
      nodes {
        id number title body
        milestone{title}
        labels(first:100){pageInfo{hasNextPage endCursor} nodes{name}}
        blockedBy(first:100){pageInfo{hasNextPage endCursor} nodes{number state repository{nameWithOwner}}}
        subIssues{totalCount}
        issueComments: comments(first:100){pageInfo{hasNextPage endCursor} nodes{authorAssociation body}}
        closedByPullRequestsReferences(first:100, includeClosedPrs:true){
          pageInfo{hasNextPage endCursor} nodes{number}}
        timelineItems(itemTypes:[CROSS_REFERENCED_EVENT], first:100){pageInfo{hasNextPage endCursor} nodes{
          ... on CrossReferencedEvent{source{
            ... on PullRequest{number repository{nameWithOwner}}}}}}
      }
    }
  }
}

query($owner:String!, $name:String!, $after:String) {
  rateLimit{cost}
  repository(owner:$owner, name:$name) {
    pullRequests(states:OPEN, first:50, after:$after) {
      totalCount pageInfo{hasNextPage endCursor}
      nodes{...pr}
    }
  }
}

fragment pr on PullRequest {
  id number state body isCrossRepository
  closingIssuesReferences(first:100){pageInfo{hasNextPage endCursor} nodes{number}}
  comments(first:100){pageInfo{hasNextPage endCursor} nodes{authorAssociation body}}
  commits(last:1){nodes{commit{statusCheckRollup{id
    contexts(first:100){pageInfo{hasNextPage endCursor} nodes{__typename
      ... on CheckRun{name status conclusion}
      ... on StatusContext{context state}}}}}}}
}
